function Header({title,copy,onAdd,add='Créer',children}:{title:string;copy:string;onAdd?:()=>void;add?:string;children?:ReactNode}){return <div className="module-head"><div><span className="eyebrow"><i/> SMARTSELL V3</span><h1>{title}</h1><p>{copy}</p></div><div className="head-actions">{children}{onAdd&&<button className="primary-btn compact" onClick={onAdd}><Plus/>{add}</button>}</div></div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){return <motion.div className="modal-backdrop" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onMouseDown={onClose}><motion.div className="modal wide-modal" initial={{opacity:0,y:20,scale:.98}} animate={{opacity:1,y:0,scale:1}} onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow"><i/> SMARTSELL</span><h2>{title}</h2></div><button className="icon-btn" onClick={onClose}><X/></button></div>{children}</motion.div></motion.div>}
function Field({label,children,wide=false}:{label:string;children:ReactNode;wide?:boolean}){return <label className={wide?'wide':''}>{label}{children}</label>}
function Empty({text}:{text:string}){return <div className="empty-state"><FileDown/><h3>{text}</h3><p>Utilisez le bouton de création pour commencer.</p></div>}
function Danger({onClick}:{onClick:()=>void}){return <button type="button" className="danger-btn" onClick={onClick}><Trash2/>Supprimer</button>}

export function SuppliersPage({admin}:{admin:boolean}){
  const[rows,setRows]=useState<Supplier[]>([]),[selected,setSelected]=useState<Supplier|null|undefined>(),[error,setError]=useState('')
  const load=()=>listSuppliers().then(setRows).catch(e=>setError(e.message));useEffect(()=>{void load()},[])
  const form=(item?:Supplier)=><form className="entity-form" onSubmit={async e=>{e.preventDefault();setError('');try{const f=Object.fromEntries(new FormData(e.currentTarget)) as Record<string,string>;await saveSupplier({...item,...f,status:f.status||'ACTIF'});setSelected(undefined);load()}catch(x){setError(x instanceof Error?x.message:'Enregistrement impossible')}}}><div className="form-grid"><Field label="Entreprise"><input name="name" required defaultValue={item?.name}/></Field><Field label="Catégorie"><input name="category" defaultValue={item?.category||''}/></Field><Field label="Contact"><input name="contact_name" defaultValue={item?.contact_name||''}/></Field><Field label="Téléphone"><input name="phone" defaultValue={item?.phone||''}/></Field><Field label="WhatsApp"><input name="whatsapp" defaultValue={item?.whatsapp||''}/></Field><Field label="E-mail"><input name="email" type="email" defaultValue={item?.email||''}/></Field><Field label="NIF / Identifiant fiscal"><input name="tax_id" defaultValue={item?.tax_id||''}/></Field><Field label="Statut"><select name="status" defaultValue={item?.status||'ACTIF'}><option>ACTIF</option><option>INACTIF</option><option>SUSPENDU</option></select></Field><Field label="Adresse" wide><input name="address" defaultValue={item?.address||''}/></Field><Field label="Notes" wide><textarea name="notes" defaultValue={item?.notes||''}/></Field></div><div className="form-actions"><button className="primary-btn compact">Enregistrer</button>{item&&admin&&<Danger onClick={async()=>{if(confirm(`Supprimer ${item.name} ?`)){await deleteSupplier(item.id);setSelected(undefined);load()}}}/>}</div></form>
  return <><Header title="Fournisseurs" copy="Prestataires, achats, contacts et pièces commerciales réunis." onAdd={()=>setSelected(null)} add="Nouveau fournisseur"/>{error&&<div className="error-banner">{error}</div>}<div className="records panel">{rows.length?rows.map(row=><article className="clickable-row" key={row.id} onClick={()=>setSelected(row)}><div className="record-main"><span className="record-avatar">FR</span><div><strong>{row.name}</strong><small>{row.category||'Fournisseur'} · {row.contact_name||'Sans contact'}</small></div></div><span className="status">{row.status}</span><span className="record-meta">{row.email||row.phone||'—'}</span><b className="record-amount">Ouvrir <ChevronRight/></b></article>):<Empty text="Aucun fournisseur"/>}</div><AnimatePresence>{selected!==undefined&&<Modal title={selected?.name||'Nouveau fournisseur'} onClose={()=>setSelected(undefined)}>{form(selected||undefined)}</Modal>}</AnimatePresence></>
}

